import { Sound, SoundMixer, SoundTransform, Video } from "@next2d/media";
const media = {
    Sound,
    SoundMixer,
    SoundTransform,
    Video
};
Object.entries(media).forEach(([key, MediaClass]) => {
    Object.defineProperty(media, key, {
        get() {
            return MediaClass;
        }
    });
});
export { media };
